-- Complete Smart Test question seed: expanded Kanji/Vocabulary plus the preserved Grammar/Reading/Listening banks.
-- KANJI and VOCABULARY: 150 questions per level. Other skills: 50 per level (2,250 questions total).
-- Safe to rerun: source question inserts use stable seed_key checks.
-- Select the existing J-LAS database, then execute this ENTIRE file in one session.
-- Save/restore the session option; Workbench Preferences do not need changing.
SET @jlas_smart_test_previous_safe_updates = @@SESSION.SQL_SAFE_UPDATES;
SET SESSION SQL_SAFE_UPDATES = 0;
SET NAMES utf8mb4;
START TRANSACTION;

-- Reserved Smart Test tag IDs: 1001-1004; textbook seed uses 1-63.
-- Rebuild order: schema -> textbook upgrade -> textbook seed -> this file.
-- Existing tags with matching codes keep their IDs; questions resolve tags by code.
INSERT INTO tag (id, code, name, tag_type) VALUES
(1001,'JLPT','Luyện thi JLPT','SITUATION'),
(1002,'BRSE','Kỹ sư cầu nối','SITUATION'),
(1003,'TRAVEL','Du lịch','SITUATION'),
(1004,'DAILY_LIFE','Đời sống hằng ngày','SITUATION')
ON DUPLICATE KEY UPDATE name=VALUES(name), tag_type=VALUES(tag_type);

-- Reclassify only this Smart Test seed family; shared tags used elsewhere are retained.
UPDATE assessment_question q
JOIN tag old_tag ON old_tag.id=q.knowledge_tag_id
JOIN tag replacement ON replacement.code=CASE old_tag.code
    WHEN 'GENERAL' THEN 'DAILY_LIFE' WHEN 'WORK' THEN 'BRSE' END
SET q.knowledge_tag_id=replacement.id
WHERE q.id > 0 AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_batch')) IN
('SMART_TEST_500_V1','KANJI_N5_N1_EXPANDED_V2','KANJI_N5_N1_DIVERSE_V3',
 'VOCAB_N5_N1_EXPANDED_V2','GRAMMAR_N5_N1_REAL_V1','READING_N5_N1_REAL_V1','LISTENING_N5_N1_V1');

UPDATE smart_test_session SET goal=CASE goal
    WHEN 'GENERAL' THEN 'DAILY_LIFE' WHEN 'WORK' THEN 'BRSE' ELSE goal END
WHERE attempt_id > 0 AND goal IN ('GENERAL','WORK');

-- Replace obsolete links/metadata only for the seed family above.
INSERT IGNORE INTO question_tag (question_id, tag_id)
SELECT qt.question_id, replacement.id FROM question_tag qt
JOIN assessment_question q ON q.id=qt.question_id
JOIN tag old_tag ON old_tag.id=qt.tag_id
JOIN tag replacement ON replacement.code=CASE old_tag.code
    WHEN 'GENERAL' THEN 'DAILY_LIFE' WHEN 'WORK' THEN 'BRSE' END
WHERE JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_batch')) IN
('SMART_TEST_500_V1','KANJI_N5_N1_EXPANDED_V2','KANJI_N5_N1_DIVERSE_V3',
 'VOCAB_N5_N1_EXPANDED_V2','GRAMMAR_N5_N1_REAL_V1','READING_N5_N1_REAL_V1','LISTENING_N5_N1_V1');

DELETE qt FROM question_tag qt
JOIN assessment_question q ON q.id=qt.question_id
JOIN tag old_tag ON old_tag.id=qt.tag_id
WHERE q.id > 0 AND old_tag.code IN ('GENERAL','WORK')
AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_batch')) IN
('SMART_TEST_500_V1','KANJI_N5_N1_EXPANDED_V2','KANJI_N5_N1_DIVERSE_V3',
 'VOCAB_N5_N1_EXPANDED_V2','GRAMMAR_N5_N1_REAL_V1','READING_N5_N1_REAL_V1','LISTENING_N5_N1_V1');

UPDATE assessment_question q
SET q.context_json=REPLACE(REPLACE(CAST(q.context_json AS CHAR), '"GENERAL"', '"DAILY_LIFE"'), '"WORK"', '"BRSE"')
WHERE q.id > 0 AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_batch')) IN
('SMART_TEST_500_V1','KANJI_N5_N1_EXPANDED_V2','KANJI_N5_N1_DIVERSE_V3',
 'VOCAB_N5_N1_EXPANDED_V2','GRAMMAR_N5_N1_REAL_V1','READING_N5_N1_REAL_V1','LISTENING_N5_N1_V1');


-- Preserve historical rows/answers, but stop selecting superseded repeated-word Kanji seeds.
UPDATE assessment_question SET is_active=0
WHERE id > 0 AND skill='KANJI' AND (
    JSON_UNQUOTE(JSON_EXTRACT(context_json, '$.seed_batch')) IN
        ('KANJI_N5_N1_EXPANDED_V2','SMART_TEST_500_V1')
    OR JSON_UNQUOTE(JSON_EXTRACT(context_json, '$.seed_version')) IN ('dev-250-v1','dev-1000-v2'));


