AND NOT EXISTS (SELECT 1 FROM assessment_question aq WHERE JSON_UNQUOTE(JSON_EXTRACT(aq.context_json, '$.seed_key'))='LISTENING-N3-07-2');

INSERT INTO assessment_question (knowledge_tag_id, skill, jlpt_level, difficulty, question_type, title, passage_html, audio_url, image_url, question_text, answer_text, option_1, option_2, option_3, option_4, correct_option, explanation, context_json)
SELECT t.id, 'LISTENING', 'N3', 'MEDIUM', 'MULTIPLE_CHOICE', '聴解・ポイント理解', '<p class="listening-transcript">女：最初の案から変わった点がいくつかありますね。理由も含めて整理しておきましょう。<br>女：試験前の勉強場所は、家の居間、駅前のカフェ、市立図書館のどれにしますか。<br>男：カフェは音楽が大きく、家では家族がテレビを見るので、最初に考えた案は難しそうです。<br>女：では、市立図書館はどうですか。<br>男：それがいいですね。静かで過去問題も借りられるから。それに決めましょう。<br>女：決まった内容と、その理由を私からみんなにメールします。<br>女：では、最終的に何をするのかを関係者に伝えます。</p>', '/audio/smart-test/listening/n3/choukai_n3_08.mp3', NULL, '二人は、試験前の勉強場所をどうすることにしましたか。', NULL, '家の居間', '駅前のカフェ', '市立図書館', 'どの案にも決めなかった', 3, '二人が最後に選んだのは「市立図書館」です。', '{"seed_batch":"LISTENING_N5_N1_V1","seed_key":"LISTENING-N3-08-1","format":"POINT_COMPREHENSION","audio_group":"choukai_n3_08","transcript":"女：最初の案から変わった点がいくつかありますね。理由も含めて整理しておきましょう。\\n女：試験前の勉強場所は、家の居間、駅前のカフェ、市立図書館のどれにしますか。\\n男：カフェは音楽が大きく、家では家族がテレビを見るので、最初に考えた案は難しそうです。\\n女：では、市立図書館はどうですか。\\n男：それがいいですね。静かで過去問題も借りられるから。それに決めましょう。\\n女：決まった内容と、その理由を私からみんなにメールします。\\n女：では、最終的に何をするのかを関係者に伝えます。","content_origin":"ORIGINAL_JLPT_STRUCTURE_INSPIRED"}' FROM tag t WHERE t.code='JLPT'
AND NOT EXISTS (SELECT 1 FROM assessment_question aq WHERE JSON_UNQUOTE(JSON_EXTRACT(aq.context_json, '$.seed_key'))='LISTENING-N3-08-1');

